import { inject } from "vue";
import type { InjectionKey } from "vue";

import type { BlockEditorContextValue } from "./types";

export const blockEditorKey: InjectionKey<BlockEditorContextValue> =
  Symbol("BlockEditor");

export const useBlockEditorContext = (): BlockEditorContextValue => {
  const context = inject(blockEditorKey, null);
  if (!context) {
    throw new Error("BlockEditor components must be used within <BlockEditor>");
  }
  return context;
};

import { Extension } from "@tiptap/core";
import type { Editor, Range } from "@tiptap/core";
import { PluginKey } from "@tiptap/pm/state";
import { Suggestion } from "@tiptap/suggestion";
import type { SuggestionOptions } from "@tiptap/suggestion";
import type { Component } from "vue";

export type OnCommandSelect = (props: { editor: Editor; range: Range }) => void;

export interface SlashCommandSuggestionItem {
  id: string;
  title: string;
  description: string;
  keywords: string[];
  icon?: Component;
  /** Hide the item unless the editor has the extensions it needs. */
  isAvailable?: (editor: Editor) => boolean;
  command: OnCommandSelect;
}

export interface SlashCommandOptions<
  Item extends SlashCommandSuggestionItem = SlashCommandSuggestionItem,
> {
  suggestion: Omit<SuggestionOptions<Item>, "editor">;
}

export const slashCommandPluginKey = new PluginKey("slashCommand");

export const SlashCommand = Extension.create<SlashCommandOptions>({
  name: "slashCommand",

  addOptions() {
    return {
      suggestion: {
        allow: ({ editor }) => !editor.isActive("codeBlock"),
        char: "/",
        command: ({ editor, range, props }) => {
          props.command({ editor, range });
        },
        pluginKey: slashCommandPluginKey,
      },
    };
  },

  addProseMirrorPlugins() {
    return [
      Suggestion({
        editor: this.editor,
        ...this.options.suggestion,
      }),
    ];
  },
});

import { computePosition, flip, shift } from "@floating-ui/dom";
import { posToDOMRect } from "@tiptap/core";
import type { Editor } from "@tiptap/core";
import { VueRenderer } from "@tiptap/vue-3";
import type { SuggestionOptions } from "@tiptap/suggestion";

import { DEFAULT_ICONS } from "./icons";
