/* Block Editor styles using --rte-* theme variables */
.rte.block-editor {
  position: relative;
  width: 100%;
}

.rte .block-editor-content {
  width: 100%;
}

.rte .block-editor-content .ProseMirror {
  outline: none;
  min-height: 200px;
  padding: 0.5rem 0 0.5rem 2rem;
  overflow: auto hidden;
  transition: opacity 150ms ease-out;
}

.rte .block-editor-content .ProseMirror p.is-editor-empty:first-child::before {
  color: var(--rte-muted-foreground);
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  transition: opacity 150ms ease-out;
}

.rte .block-editor-content .ProseMirror .is-empty::before {
  color: var(--rte-muted-foreground);
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  transition: opacity 150ms ease-out;
}

/* Tiptap drag handle (from @tiptap/extension-drag-handle-react) */

.rte .drag-handle {
  display: flex;
  align-items: center;
  gap: 0.12rem;
  height: 1.5rem;
  border-radius: calc(var(--rte-radius) - 4px);
  background: transparent;
  color: var(--rte-muted-foreground);
  cursor: grab;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    opacity 150ms ease-out,
    transform 100ms ease-out,
    top 150ms ease-out,
    left 150ms ease-out;
  opacity: 0;
}

.rte .drag-handle:hover {
  opacity: 1;
}

.rte .drag-handle:active {
  cursor: grabbing;
  transform: scale(0.9);
}

.rte .block-editor-content .ProseMirror:hover ~ .drag-handle,
.rte .block-editor-content:hover .drag-handle {
  opacity: 1;
}

.rte .block-editor-add-block {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.125rem;
  height: 1.125rem;
  padding: 0;
  border: none;
  border-radius: calc(var(--rte-radius) - 4px);
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.rte .block-editor-add-block:hover {
  background: var(--rte-accent);
  color: var(--rte-accent-foreground);
}

.rte .block-editor-add-block:active {
  transform: scale(0.9);
}

.rte .block-editor-add-block svg {
  width: 0.875rem;
  height: 0.875rem;
}

.rte .block-editor-drag-handle-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.125rem;
  height: 1.125rem;
}

.rte .block-editor-drag-handle-icon svg {
  width: 0.875rem;
  height: 0.875rem;
}

