/* ── Bubble Menu & Dropdowns ── */
@keyframes bubble-pop-in {
  0% {
    opacity: 0;
    transform: scale(0.98) translateY(6px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.rte .rte-bubble-root {
  z-index: 30;
}

.rte .block-editor-bubble-menu {
  display: flex;
  align-items: center;
  height: 2.25rem;
  background: var(--rte-popover);
  border: 1px solid var(--rte-border);
  border-radius: var(--rte-radius);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  padding: 0 0.25rem;
  animation: bubble-pop-in 0.25s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.rte .block-editor-bubble-group {
  display: flex;
  align-items: center;
  gap: 1px;
}

.rte .block-editor-bubble-btn {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  height: 1.75rem;
  padding: 0 0.375rem;
  border: none;
  border-radius: calc(var(--rte-radius) - 4px);
  background: transparent;
  color: var(--rte-popover-foreground);
  cursor: pointer;
  font-size: 0.8125rem;
  white-space: nowrap;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    transform 100ms ease-out;
}

.rte .block-editor-bubble-btn > svg {
  width: 1rem;
  height: 1rem;
}

.rte .block-editor-bubble-btn:hover {
  background: var(--rte-accent);
  color: var(--rte-accent-foreground);
}

.rte .block-editor-bubble-btn:focus-visible {
  outline: 2px solid var(--rte-ring);
  outline-offset: -2px;
}

.rte .block-editor-bubble-btn:active {
  transform: scale(0.96);
}

.rte .block-editor-bubble-btn--active {
  color: var(--rte-primary);
  background: var(--rte-accent);
}

.rte .block-editor-copy-icon {
  display: inline-flex;
  width: 1rem;
  height: 1rem;
  transition:
    transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
    color 0.15s ease;
}

.rte .block-editor-copy-icon > svg {
  width: 1rem;
  height: 1rem;
}

.rte .block-editor-copy-icon--copied {
  color: var(--rte-primary);
  transform: scale(1.15);
}

.rte .block-editor-bubble-btn-text {
  max-width: 5rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rte .block-editor-bubble-separator {
  width: 1px;
  height: 1.25rem;
  background: var(--rte-border);
  margin: 0 0.125rem;
  flex-shrink: 0;
}

.rte .block-editor-bubble-overlay {
  position: fixed;
  inset: 0;
  z-index: 999;
}

.rte .block-editor-bubble-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 1000;
  min-width: 150px;
  background: var(--rte-popover);
  border: 1px solid var(--rte-border);
  border-radius: var(--rte-radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  padding: 0.25rem;
  margin-top: 4px;
  transform-origin: top left;
  animation: bubble-pop-in 0.25s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.rte .block-editor-bubble-dropdown--align {
  min-width: 130px;
}

.rte .block-editor-bubble-dropdown--language {
  min-width: 160px;
  max-height: 13rem;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

.rte .block-editor-bubble-dropdown-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  position: relative;
  z-index: 1;
  width: 100%;
  padding: 0.375rem 0.5rem;
  font-size: 0.8125rem;
  color: var(--rte-muted-foreground);
  background: transparent;
  border: none;
  border-radius: calc(var(--rte-radius) - 4px);
  cursor: pointer;
  text-align: left;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.rte .block-editor-bubble-dropdown-item:hover,
.rte .block-editor-bubble-dropdown-item:focus-visible {
  color: var(--rte-foreground);
}

.rte .block-editor-bubble-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--rte-radius) - 4px);
  background: color-mix(in srgb, var(--rte-primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.rte .block-editor-bubble-dropdown-pill--visible {
  opacity: 1;
}

.rte .block-editor-bubble-dropdown-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--rte-muted-foreground);
  width: 1rem;
  height: 1rem;
}

.rte .block-editor-bubble-dropdown-icon svg {
  width: 100%;
  height: 100%;
}

.rte .block-editor-bubble-dropdown-item--active .block-editor-bubble-dropdown-icon {
  color: var(--rte-primary);
}

.rte .block-editor-bubble-dropdown-item:active {
  transform: scale(0.98);
}

.rte .block-editor-bubble-dropdown-item--active {
  color: var(--rte-primary);
  background-color: color-mix(in srgb, var(--rte-primary) 10%, transparent);
}

.rte .block-editor-bubble-dropdown-divider {
  height: 1px;
  background: var(--rte-border);
  margin: 0.25rem 0;
}

.rte .block-editor-bubble-dropdown-item--danger {
  color: var(--rte-destructive, #ef4444);
}

.rte .block-editor-bubble-dropdown-item--danger:hover {
  background: color-mix(in srgb, var(--rte-destructive, #ef4444) 10%, transparent);
