/* ── Typography & Content ── */

.rte .block-editor-content .ProseMirror h1 {
  font-size: 1.875rem;
  font-weight: 700;
  line-height: 1.2;
  margin: 0.5em 0 0.25em;
}

.rte .block-editor-content .ProseMirror h2 {
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.25;
  margin: 0.5em 0 0.25em;
}

.rte .block-editor-content .ProseMirror h3 {
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
  margin: 0.5em 0 0.25em;
}

.rte .block-editor-content .ProseMirror p {
  margin: 0.25em 0;
  line-height: 1.6;
}

.rte .block-editor-content .ProseMirror ul {
  list-style-type: disc;
  padding-left: 1.5rem;
  margin: 0.25em 0;
}

.rte .block-editor-content .ProseMirror ol {
  list-style-type: decimal;
  padding-left: 1.5rem;
  margin: 0.25em 0;
}

.rte .block-editor-content .ProseMirror li {
  margin: 0.125em 0;
}

.rte .block-editor-content .ProseMirror li p {
  margin: 0;
}

.rte .block-editor-content .ProseMirror blockquote {
  border-left: 3px solid var(--rte-border);
